  dateFrValidator(control) {
    const value = control.value;
    if (!value)
      return null;
    const regex = /^(0[1-9]|[12][0-9]|3[01])\/(0[1-9]|1[0-2])\/\d{4}$/;
    return regex.test(value) ? null : { dateFormat: "Le format doit \xEAtre JJ/MM/AAAA" };
  }
